INSERT INTO `bi_theme` (`id`, `dashboard_style_cfg`, `name`, `render_code`, `graph_render_type`, `deleted`)
VALUES
	('4', '{\"css\":\".kanban {\\n    .header-title {\\n    border-left:10px solid rgba(242, 48, 125, 0.868);\\n    margin-left: 15px;\\n    margin-top: 10px;\\n    padding-left: 10px;\\n    font-size: 20px;\\n    line-height: 22px;\\n    font-weight: 500;\\n}\\n.mobile {\\n    .header-title {\\n        font-size: 15px;\\n        line-height: 15px;\\n        .time {\\n            line-height: 10px;\\n            font-size: 10px;\\n        }\\n    }\\n}\\n.header {\\n    padding: 0 2px;\\n    align-items: flex-start;\\n}\\n\\n}\\n// .pc {\\n    .chart-group-container {\\n        border-radius: 10px;\\n        --tw-shadow: 0 10px 15px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);\\n        --tw-shadow-colored: 0 10px 15px -5px var(--tw-shadow-color), 0 8px 10px -6px var(--tw-shadow-color);\\n        box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);\\n        .chart-container {\\n            border-radius: 0;\\n            box-shadow: none;\\n        }\\n    }\\n\\n    .chart-container,.filters-container {\\n        border-radius: 10px;\\n        --tw-shadow: 0 10px 15px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);\\n        --tw-shadow-colored: 0 10px 15px -5px var(--tw-shadow-color), 0 8px 10px -6px var(--tw-shadow-color);\\n        box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);\\n    }\\n    .kanban-item {\\n        .dashboard-container {\\n            padding-bottom: 30px;\\n        }\\n    }\\n// }\\n.dashboard-container {\\n    background-color: rgba(255,99,71,.1);;\\n}\\n.chart-container, .chart-group-container {\\n    &::before {\\n        content: \'\'; /* 必须设置内容，才能显示伪元素 */\\n        position: absolute; /* 绝对定位覆盖整个容器 */\\n        top: 0;\\n        left: 0;\\n        width: 100%;\\n        height: 100%;\\n        background: rgba(255,133,192,.1);\\n        z-index: 1; /* 确保覆盖在内容上方 */\\n        pointer-events: none; /* 不影响鼠标事件，让内容可点击 */\\n    }\\n}\\n.chart-type-selector svg {\\n    fill: #FF85C0;\\n}\\n.indicator-container .value1 .label, .headre-title .time  {\\n    color: rgba(255,133,192,.5);\\n}\\n.indicator-container .value1 .number,\\n.chart-container .title, \\n.header-title,\\n.chart-table button  {\\n    color: #FF85C0;\\n}\\n.chart-table table {\\n    background-color: transparent!important;\\n}\\n.dark {\\n    .dashboard-container {\\n        background-color: rgba(255,99,71,.1);\\n    }\\n    .chart-container, .chart-group-container {\\n        &::before {\\n            background: rgba(255,99,71,.1);\\n        }\\n    }\\n    .chart-type-selector svg {\\n        fill: #FF6347;\\n    }\\n    .chart-container {\\n        background: #1E1E1E;\\n    }\\n    .chart-group-container {\\n        background: #1E1E1E;\\n    }\\n    .indicator-container .value1 .label, .headre-title .time  {\\n        color: rgba(255,99,71,.5);\\n    }\\n    .indicator-container .value1 .number,\\n    .chart-container .title, \\n    .header-title,\\n    .chart-table button  {\\n        color: #FF6347;\\n    }\\n}\\n@img-url: \'http://fusb.top/data/images/icons/\';\\n\\n// 定义通用函数\\n.generate-icons(@icons, @i: 1) when (@i <= length(@icons)) {\\n  // 获取当前图标名称\\n  @value: extract(@icons, @i);\\n  @name: ~\'@{value}\';\\n\\n  // 生成动态样式\\n  #@{name} .indicator-container .icon {\\n    background-image: url(\'@{img-url}@{b_name}@{name}.png\');\\n  }\\n\\n  // 递归调用生成样式\\n  .generate-icons(@icons, @i + 1);\\n}\\n.indicator-container {\\n    align-items: center;\\n    gap: 1rem;\\n}\\n.indicator-container .icon {\\n  background-size: cover;\\n  background-repeat: no-repeat;\\n  height: 50px;\\n  width: 50px;\\n}\"}', '彩色主题', 'function main(args) {\n    try {\n        const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark } = args\n        const lightThemeColors = [\n  \'#FF85C0\', // 粉红\n  \'#4E91FC\', // 亮蓝\n  \'#67C23A\', // 鲜绿\n  \'#F56C6C\', // 温暖红\n  \'#E6A23C\', // 橙色\n  \'#909399\', // 中性灰\n  \'#A6C1EE\', // 柔和蓝\n  \'#79D4D5\', // 青绿色\n  \'#FFD700\', // 金色\n];\n\n// 暗色主题颜色，偏向深沉和神秘\nconst darkThemeColors = [\n  \'#FF6347\', // 番茄红\n  \'#2C3E50\', // 深蓝灰\n  \'#34495E\', // 蓝灰\n  \'#8E44AD\', // 紫色\n  \'#3498DB\', // 明亮蓝\n  \'#16A085\', // 绿松石\n  \'#E74C3C\', // 明亮红\n  \'#F1C40F\', // 黄色\n  \'#95A5A6\', // 灰绿\n];\n  // 根据 `dark` 字段选择主题色\n  const themeColors = dark ? darkThemeColors : lightThemeColors;\n        const list = transpose(rows)\n        let option: any = {\n               color: themeColors, // 设置主题色\n    legend: {\n      orient: \'horizontal\',\n    },\n    backgroundColor: dark ? \'#1E1E1E\' : \'#fff\', // 根据 dark 设置背景色\n        }\n        if (chartType === \'COLUMN\' || chartType === \'LINE\') {\n            option = {\n                ...option,\n                legend: y.length == 1 ? null : option.legend,\n                tooltip: {\n                    trigger: \'axis\'\n                },\n                xAxis: { type: \'category\', data: list[0] },\n                yAxis: {\n                    splitLine: {\n                        show: false\n                    }\n                },\n                series: y.map((i, idx) => {\n                    const index = idx + x.length\n                    return {\n                        name: i,\n                        data: list[index], type: { \'LINE\': \'line\', \'COLUMN\': \'bar\' }[chartType]\n                    }\n                })\n            }\n            return { option }\n        } else if (chartType === \'PIE\') {\n            option = {\n                ...option,\n                tooltip: {\n                    trigger: \'item\',\n                },\n                legend: {\n                    type: \'scroll\', // 支持滚动或分页\n                    orient: \'vertical\', // 垂直布局\n                    right: 10, // 距离右边的距离\n                    top: \'middle\', // 垂直居中\n                    pageIconColor: \'#333\', // 分页按钮颜色\n                    pageTextStyle: {\n                        color: \'#333\', // 分页文字样式\n                    },\n                    formatter: (name: string) => {\n                        const item = option.series[0].data.find((i: any) => i.name === name);\n                        return `${name}: ${item?.value}`; // 显示名称和数值\n                    },\n                    data: [], // 后续动态填充\n                },\n                series: [\n                    {\n                        name: x[0],\n                        type: \'pie\',\n                        radius: \'50%\',\n                        left: 0, // 靠左对齐\n                        center: [\'35%\', \'50%\'], // 调整饼图中心点\n                        data: [], // 后续动态填充\n                        emphasis: {\n                            itemStyle: {\n                                shadowBlur: 10,\n                                shadowOffsetX: 0,\n                                shadowColor: \'rgba(0, 0, 0, 0.5)\',\n                            },\n                        },\n                    },\n                ],\n            };\n\n            // 动态生成数据和排序逻辑\n            if (x.length > 0) {\n                option.series[0].data = rows.map((i) => ({ value: i[1], name: i[0] || \'-\' }));\n            } else {\n                option.series[0].data = list.map((i, idx) => ({ name: y[idx], value: i[0] }));\n            }\n\n            // 根据数值大小排序数据\n            option.series[0].data.sort((a: any, b: any) => b.value - a.value);\n            // 同步 legend 数据顺序\n            option.legend.data = option.series[0].data.map((i: any) => i.name);\n        } else if (chartType === \'MAP\') {\n\n            function jenksNaturalBreaks(data, splitNumber) {\n                const sorted = [...data].sort((a, b) => a - b);\n                const breaks = [Math.min(...data)];\n                for (let i = 1; i < splitNumber; i++) {\n                    const chunkSize = Math.floor(sorted.length / splitNumber);\n                    breaks.push(sorted[chunkSize * i]);\n                }\n                breaks.push(Math.max(...data));\n                return breaks.map((min, idx) => ({\n                    min,\n                    max: breaks[idx + 1] || breaks[idx],\n                })).slice(0, -1);\n            }\n            const intervals = jenksNaturalBreaks(rows.map(i => i[x.length]), 5);\n            // 提取省份和值\n            const mapData = rows.map((col, index) => ({\n                name: rows[index][0], // 省份\n                value: rows[index][x.length] // 值\n            }));\n            // 返回 ECharts 配置\n            // @ts-ignore\n            option = {\n                ...option,\n                visualMap: {\n                    type: \'piecewise\', // 设置为分段模式\n                    left: \'right\', // 视觉图例位置\n                    top: \'center\',\n                    width: \'10%\', // 可选：控制宽度\n                    height: \'80%\', // 可选：控制高度\n                    min: 0, // 数据的最小值\n                    max: 1000, // 数据的最大值\n                    splitNumber: 5, // 分成几段（如果设置了 pieces，会忽略 splitNumber）\n                    pieces: intervals.map((i, idx) => ({\n                        min: i.min,\n                        max: i.max,\n                        color: [\'#d94e5d\', \'#eac736\', \'#50a3ba\', \'#91c7ae\', \'#516b91\'][intervals.length - idx - 1],\n                    })),\n                    text: [\'高\', \'低\'], // 文本显示（顶部为高，底部为低）\n                    textStyle: {\n                        color: \'#000\' // 文本颜色\n                    },\n                    show: true, // 是否显示 visualMap 组件\n                },\n                series: [\n                    {\n                        type: \'map\',  // 保持为 map 类型\n                        map: \'china\',\n                        roam: true, // 启用地图的缩放和平移\n                        label: {\n                            show: true, // 显示省份名称\n                            color: \'#444\',  // 标签文字颜色\n                        },\n                        top: \'1%\',\n                        zoom: 1.5,\n                        center: [104.114129, 37.550339],\n                        tooltip: {\n                            trigger: \'item\',  // 设置为 item 类型，显示每个省份的 tooltip\n                            formatter: \'{b}: {c}\',  // 显示省份名称和对应的值\n                        },\n                        geoIndex: 0,\n                        data: mapData\n                    }\n                ]\n            }\n        } else if (chartType === \'WORD_CLOUD\') {\n            const colorPalette = [\'#5470C6\', \'#91CC75\', \'#FAC858\', \'#EE6666\', \'#73C0DE\', \'#3BA272\', \'#FC8452\', \'#9A60B4\', \'#EA7CCC\'];\n            const wordCloudData = rows.map(row => ({\n                name: row[0], // 从 rows 中取出 xKey 列的数据\n                value: row[1] // 从 rows 中取出 yKey 列的数据\n            }));\n\n            option = {\n                animation: false,\n                ...option,\n                tooltip: {\n                    show: true,\n                    formatter: function (params) {\n                        return `${params.name}: ${params.value}`;\n                    }\n                },\n                series: [{\n                    type: \'wordCloud\',\n                    shape: \'circle\', // 默认圆形\n                    sizeRange: [12, 60], // 字体大小范围\n                    // rotationRange: [-90, 90], // 字体旋转范围\n                    rotationStep: 45, // 每次旋转的角度间隔\n                    gridSize: 8, // 单词间的间距\n                    rotationRange: [0, 0], // 禁止旋转，保证方向固定\n                    layoutAnimation: false, // 关闭布局动画\n                    textStyle: {\n                        color: function (params) {\n                            // 根据数据索引选择颜色\n                            return colorPalette[params.dataIndex % colorPalette.length];\n                        }\n                    },\n                    data: wordCloudData // 设置词云数据\n                }]\n            }\n        } else if (chartType === \'FUNNEL\') {\n            // 统一处理漏斗数据的逻辑\n            const generateFunnelData = (x: string[], y: string[]) => {\n                if (x.length === 0) {\n                    // 没有 X 轴时，将列名作为漏斗层级，值来自行\n                    return y.map((column, idx) => ({\n                        name: column,\n                        value: rows[0][idx],\n                    }));\n                } else if (x.length === 1 && y.length === 1) {\n                    // 有 X 轴时，根据 group by X 汇总生成漏斗层级\n                    const xValues = rows.map(row => row[columns.indexOf(x[0])]);\n                    const yValues = rows.map(row => row[columns.indexOf(y[0])]);\n                    const grouped = xValues.reduce((acc: Record<string, number>, key, idx) => {\n                        acc[key] = (acc[key] || 0) + yValues[idx];\n                        return acc;\n                    }, {});\n                    return Object.entries(grouped).map(([name, value]) => ({ name, value }));\n                }\n                return [];\n            };\n\n            const funnelData = generateFunnelData(x, y);\n\n            // 构建漏斗图配置\n            option = {\n                ...option,\n                series: [\n                    {\n                        name: \'漏斗图\',\n                        type: \'funnel\',\n                        data: funnelData,\n                        sort: \'none\', // 按值降序排列\n                        label: {\n                            position: \'right\', // 标签位置在右侧\n                            formatter: (params: any) => {\n                                const index = params.dataIndex;\n                                const currentValue = params.data.value;\n                                const nextValue = funnelData[index + 1]?.value;\n                                if (nextValue !== undefined) {\n                                    const conversionRate = ((nextValue / currentValue) * 100).toFixed(2);\n                                    return `${params.name}\\n${params.value}\\n转化率: ${conversionRate}%`;\n                                }\n                                return `${params.name}\\n${params.value}`;\n                            },\n                        },\n                        labelLine: {\n                            show: true,\n                            length: 10,\n                            length2: 20,\n                        },\n                        itemStyle: {\n                            borderColor: \'#fff\',\n                            borderWidth: 1,\n                        },\n                    },\n                ],\n            };\n        } else if (chartType === \'GUAGE\') {\n            const maxValue = rows[0][rows[0].length - 1]; // 最后一个值作为最大值\n            const scoreData = rows[0].slice(0, -1); // 其余值作为环数据\n\n            const gaugeData = scoreData.map((value, index) => ({\n                value: ((value / maxValue) * 100).toFixed(2), // 转为百分比\n                name: y[index], // 使用 y[index] 作为名称\n                title: {\n                    offsetCenter: [\'0%\', `${-40 + index * 30}%`] // 动态调整标题位置\n                },\n                detail: {\n                    valueAnimation: true,\n                    offsetCenter: [\'0%\', `${-30 + index * 30}%`] // 动态调整详情位置\n                }\n            }));\n\n            option = {\n                ...option,\n                series: [\n                    {\n                        type: \'gauge\',\n                        startAngle: 90,\n                        endAngle: -270,\n                        pointer: {\n                            show: false\n                        },\n                        progress: {\n                            show: true,\n                            overlap: false,\n                            roundCap: true,\n                            clip: false,\n                            itemStyle: {\n                                borderWidth: 1,\n                                borderColor: \'#464646\'\n                            }\n                        },\n                        data: gaugeData,\n                        title: {\n                            fontSize: 14\n                        },\n                        detail: {\n                            width: 50,\n                            height: 14,\n                            fontSize: 14,\n                            color: \'inherit\',\n                            borderColor: \'inherit\',\n                            borderRadius: 20,\n                            borderWidth: 1,\n                            formatter: \'{value}%\'\n                        }\n                    }\n                ]\n            }\n        }\n        return { option }\n    } catch (ex) {\n        console.error(ex)\n    }\n}', 'echarts', '0'),
	('5', '{\"css\":\".kanban {\\n  .header-title {\\n    margin-left: 15px;\\n    margin-top: 10px;\\n    padding-left: 10px;\\n    font-size: 20px;\\n    line-height: 22px;\\n    font-weight: 500;\\n  }\\n\\n  .mobile {\\n    .header-title {\\n      font-size: 15px;\\n      line-height: 15px;\\n\\n      .time {\\n        line-height: 10px;\\n        font-size: 10px;\\n      }\\n    }\\n  }\\n\\n  .header {\\n    padding: 0 2px;\\n    align-items: flex-start;\\n  }\\n}\\n\\n@img-url: \'http://fusb.top/data/images/icons/\';\\n\\n// 定义通用函数\\n.generate-icons(@icons, @i: 1) when (@i <=length(@icons)) {\\n  // 获取当前图标名称\\n  @value: extract(@icons, @i);\\n  @name: ~\'@{value}\';\\n\\n  // 生成动态样式\\n  #@{name} .indicator-container .icon {\\n    background-image: url(\'@{img-url}@{b_name}@{name}.png\');\\n  }\\n\\n  // 递归调用生成样式\\n  .generate-icons(@icons, @i + 1);\\n}\\n\\n.indicator-container {\\n  align-items: center;\\n  gap: 1rem;\\n}\\n\\n.indicator-container .icon {\\n  background-size: cover;\\n  background-repeat: no-repeat;\\n  height: 50px;\\n  width: 50px;\\n}\"}', '默认主题', 'function main(args) {\n    const { config, chartType } = args\n    const legend = config.option.legend;\n    legend && (legend.orient = chartType === \'PIE\' ? \'vertical\' : \'horizontal\');\n    config.option.backgroundColor = \'transparent\'\n    return config\n}', 'echarts', '0');
INSERT INTO `bi_chart_component` (`id`, `name`, `description`, `props`, `code`, `enabled`, `create_time`, `update_by`, `update_time`, `deleted`, `create_by`, `sort`, `type`, `icon`)
VALUES
	('1', '柱状图', '一个比较简单的柱状图', '{\"icon\": \"icon-column\", \"limit\": [{\"x\": [0, 2], \"y\": [1, 100]}], \"script\": \"function main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    const list = transpose(rows)\\n    let option = {\\n        legend: y.length == 1 ? null : {},\\n        tooltip: {\\n            trigger: \'axis\'\\n        },\\n        grid: {\\n            left: mobile ? \'20%\' : \'10%\', // 根据设备调整左边距\\n            right: \'5%\', // 保留右边距\\n            top: \'20%\',\\n            bottom: \'20%\'\\n        },\\n        xAxis: {\\n            type: \'category\',\\n            data: list[0],\\n            // axisLabel: {\\n            //     rotate: 45, // 标签倾斜 45 度\\n            //     fontSize: mobile ? 10 : 12 // 调整字体大小\\n            // }\\n        },\\n        yAxis: {\\n            splitLine: {\\n                show: false\\n            }\\n        },\\n        series: y.map((i, idx) => {\\n            const index = idx + x.length\\n            return {\\n                name: i,\\n                data: list[index], type: { \'LINE\': \'line\', \'COLUMN\': \'bar\' }[chartType]\\n            }\\n        })\\n    }\\n    return { option }\\n}\"}', 'COLUMN', '1', '0', '1', '1737464461699', '0', '', '1', 'echarts', 'icon-column'),
	('2', '饼图', '一个比较简单的饼图', '{\"icon\": \"icon-pie\", \"limit\": [{\"x\": 1, \"y\": 1}, {\"x\": 0, \"y\": [2, 100]}], \"script\": \"function main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    const list = transpose(rows)\\n    let option = {\\n        tooltip: {\\n            trigger: \'item\',\\n        },\\n        legend: {\\n            type: \'scroll\', // 支持滚动或分页\\n            orient: \'vertical\', // 垂直布局\\n            right: 10, // 距离右边的距离\\n            top: \'middle\', // 垂直居中\\n            pageIconColor: \'#333\', // 分页按钮颜色\\n            pageTextStyle: {\\n                color: \'#333\', // 分页文字样式\\n            },\\n            formatter: (name: string) => {\\n                const item = option.series[0].data.find((i: any) => i.name === name);\\n                return `${name}: ${item?.value}`; // 显示名称和数值\\n            },\\n            data: [] as any[], // 后续动态填充\\n        },\\n        series: [\\n            {\\n                name: x[0],\\n                type: \'pie\',\\n                radius: \'50%\',\\n                left: 0, // 靠左对齐\\n                center: [\'35%\', \'50%\'], // 调整饼图中心点\\n                data: [], // 后续动态填充\\n                emphasis: {\\n                    itemStyle: {\\n                        shadowBlur: 10,\\n                        shadowOffsetX: 0,\\n                        shadowColor: \'rgba(0, 0, 0, 0.5)\',\\n                    },\\n                },\\n            },\\n        ],\\n    };\\n\\n    // 动态生成数据和排序逻辑\\n    if (x.length > 0) {\\n        option.series[0].data = rows.map((i) => ({ value: i[1], name: i[0] || \'-\' }));\\n    } else {\\n        option.series[0].data = list.map((i, idx) => ({ name: y[idx], value: i[0] }));\\n    }\\n\\n    // 根据数值大小排序数据\\n    option.series[0].data.sort((a: any, b: any) => b.value - a.value);\\n    // 同步 legend 数据顺序\\n    option.legend.data = option.series[0].data.map((i: any) => i.name);\\n    return { option }\\n}\"}', 'PIE', '1', '0', '1', '1737464571139', '0', '', '2', 'echarts', 'icon-pie'),
	('3', '折线图', '一个比较简单的折线图', '{\"icon\": \"icon-line\", \"limit\": [{\"x\": [1, 2], \"y\": [1, 100]}], \"script\": \"function main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    const list = transpose(rows)\\n    let option: any = {\\n        legend: {\\n            orient: \'horizontal\',\\n        },\\n        backgroundColor: \'transparent\'\\n    }\\n    option = {\\n        ...option,\\n        legend: y.length == 1 ? null : option.legend,\\n        tooltip: {\\n            trigger: \'axis\'\\n        },\\n        grid: {\\n            left: mobile ? \'20%\' : \'10%\', // 根据设备调整左边距\\n            right: \'5%\', // 保留右边距\\n            top: \'20%\',\\n            bottom: \'20%\'\\n        },\\n        xAxis: {\\n            type: \'category\',\\n            data: list[0],\\n            // axisLabel: {\\n            //     rotate: 45, // 标签倾斜 45 度\\n            //     fontSize: mobile ? 10 : 12 // 调整字体大小\\n            // }\\n        },\\n        yAxis: {\\n            splitLine: {\\n                show: false\\n            }\\n        },\\n        series: y.map((i, idx) => {\\n            const index = idx + x.length\\n            return {\\n                name: i,\\n                data: list[index], type: { \'LINE\': \'line\', \'COLUMN\': \'bar\' }[chartType]\\n            }\\n        })\\n    }\\n    return { option }\\n}\"}', 'LINE', '1', '0', '1', '1737453310450', '0', '', '3', 'echarts', 'icon-line'),
	('4', '水波图', '一个比较简单的水波图', '{\"icon\": \"icon-liquid\", \"limit\": [{\"x\": 0, \"y\": 1}], \"script\": \"function main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    const list = transpose(rows)\\n    let option: any = {\\n        legend: {\\n            orient: \'horizontal\',\\n        },\\n        backgroundColor: \'transparent\'\\n    }\\n    return { option }\\n}\"}', 'LIQUID', '1', '0', '1', '1737452852353', '0', '', '4', 'echarts', 'icon-liquid'),
	('5', '词云', '一个比较简单的词云', '{\"icon\": \"icon-word_cloud\", \"limit\": [{\"x\": 1, \"y\": 1}], \"script\": \"function main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    let option: any = {\\n        legend: {\\n            orient: \'horizontal\',\\n        },\\n        backgroundColor: \'transparent\'\\n    }\\n    const colorPalette = [\'#5470C6\', \'#91CC75\', \'#FAC858\', \'#EE6666\', \'#73C0DE\', \'#3BA272\', \'#FC8452\', \'#9A60B4\', \'#EA7CCC\'];\\n    const wordCloudData = rows.map(row => ({\\n        name: row[0], // 从 rows 中取出 xKey 列的数据\\n        value: row[1] // 从 rows 中取出 yKey 列的数据\\n    }));\\n\\n    option = {\\n        animation: false,\\n        ...option,\\n        tooltip: {\\n            show: true,\\n            formatter: function (params) {\\n                return `${params.name}: ${params.value}`;\\n            }\\n        },\\n        series: [{\\n            type: \'wordCloud\',\\n            shape: \'circle\', // 默认圆形\\n            sizeRange: [12, 60], // 字体大小范围\\n            // rotationRange: [-90, 90], // 字体旋转范围\\n            rotationStep: 45, // 每次旋转的角度间隔\\n            gridSize: 8, // 单词间的间距\\n            rotationRange: [0, 0], // 禁止旋转，保证方向固定\\n            layoutAnimation: false, // 关闭布局动画\\n            textStyle: {\\n                color: function (params) {\\n                    // 根据数据索引选择颜色\\n                    return colorPalette[params.dataIndex % colorPalette.length];\\n                }\\n            },\\n            data: wordCloudData // 设置词云数据\\n        }]\\n    }\\n    return { option }\\n}\"}', 'WORD_CLOUD', '1', '0', '1', '1737453121616', '0', '', '5', 'echarts', 'icon-word_cloud'),
	('6', '计量图', '一个比较简单的计量图', '{\"icon\": \"icon-guage\", \"limit\": [{\"x\": 0, \"y\": [1, 100]}], \"script\": \"function main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    const list = transpose(rows)\\n    let option: any = {\\n        legend: {\\n            orient: \'horizontal\',\\n        },\\n        backgroundColor: \'transparent\'\\n    }\\n    const { targetType, targetValue, targetColumn } = config;\\n\\n    let maxValue: number;\\n    let scoreData: number[];\\n\\n    // 判断目标值来源\\n    if (targetType === \'value\') {\\n        // 目标值直接是配置中的 `targetValue`\\n        maxValue = targetValue;\\n        scoreData = rows[0]; // 所有列作为环数据\\n    } else if (targetType === \'column\') {\\n        // 目标值是列下标对应的值\\n        maxValue = rows[0][targetColumn]; // 指定列的值为目标值\\n        scoreData = rows[0].filter((_, idx) => idx !== targetColumn); // 剩余列作为环数据\\n    } else {\\n        // throw new Error(`Unsupported targetType: ${targetType}`);\\n        maxValue = rows[0][0]; // 指定列的值为目标值\\n        scoreData = rows[0].filter((_, idx) => idx !== 0);\\n    }\\n\\n    // console.log(\'最大值:\', maxValue, \'环数据:\', scoreData);\\n\\n    const gaugeData = scoreData.map((value, index) => ({\\n        value: ((value / maxValue) * 100).toFixed(2), // 转为百分比\\n        name: y[index], // 使用 y[index] 作为名称\\n        title: {\\n            offsetCenter: [\'0%\', `${-40 + index * 30}%`] // 动态调整标题位置\\n        },\\n        detail: {\\n            valueAnimation: true,\\n            offsetCenter: [\'0%\', `${-30 + index * 30}%`] // 动态调整详情位置\\n        }\\n    }));\\n\\n    // console.log(\'仪表盘数据:\', gaugeData, \'配置:\', config);\\n\\n    option = {\\n        ...option,\\n        series: [\\n            {\\n                type: \'gauge\',\\n                startAngle: 90,\\n                endAngle: -270,\\n                pointer: {\\n                    show: false\\n                },\\n                progress: {\\n                    show: true,\\n                    overlap: false,\\n                    roundCap: true,\\n                    clip: false,\\n                    itemStyle: {\\n                        borderWidth: 1,\\n                        borderColor: \'#464646\'\\n                    }\\n                },\\n                axisLine: {\\n                    show: false // 隐藏刻度轴线\\n                },\\n                splitLine: {\\n                    show: false // 隐藏刻度分隔线\\n                },\\n                axisTick: {\\n                    show: false // 隐藏刻度小线\\n                },\\n                axisLabel: {\\n                    show: false // 隐藏刻度标签\\n                },\\n                data: gaugeData,\\n                title: {\\n                    fontSize: 14\\n                },\\n                detail: {\\n                    width: 50,\\n                    height: 14,\\n                    fontSize: 14,\\n                    color: \'inherit\',\\n                    borderColor: \'inherit\',\\n                    borderRadius: 20,\\n                    borderWidth: 1,\\n                    formatter: \'{value}%\'\\n                }\\n            }\\n        ]\\n    };\\n    return { option }\\n}\", \"confItemsMap\": {\"目标值配置\": [{\"label\": \"值类型\", \"options\": [{\"label\": \"指标列\", \"value\": \"column\"}, {\"label\": \"数值\", \"value\": \"value\"}], \"fieldName\": \"targetType\", \"componentType\": \"segmented\"}, {\"label\": \"值\", \"fieldName\": \"targetValue\", \"componentType\": \"input\", \"conditionExpression\": \"values.targetType === \'value\'\"}, {\"label\": \"指标列\", \"fieldName\": \"targetColumn\", \"columnOptions\": \"y\", \"componentType\": \"select\", \"conditionExpression\": \"values.targetType === \'column\'\"}]}}', 'GUAGE', '1', '0', '1', '1739262070479', '0', '', '6', 'echarts', 'icon-guage'),
	('7', '地图', '一个比较简单的地图', '{\"icon\": \"icon-map\", \"limit\": [{\"x\": 1, \"y\": 1}], \"script\": \"function jenksNaturalBreaks(data, splitNumber) {\\n    const sorted = [...data].sort((a, b) => a - b);\\n    const breaks = [Math.min(...data)];\\n    for (let i = 1; i < splitNumber; i++) {\\n        const chunkSize = Math.floor(sorted.length / splitNumber);\\n        breaks.push(sorted[chunkSize * i]);\\n    }\\n    breaks.push(Math.max(...data));\\n    return breaks.map((min, idx) => ({\\n        min,\\n        max: breaks[idx + 1] || breaks[idx],\\n    })).slice(0, -1);\\n}\\n\\nfunction main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    const list = transpose(rows)\\n    let option: any = {\\n        legend: {\\n            orient: \'horizontal\',\\n        },\\n        backgroundColor: \'transparent\'\\n    }\\n    const intervals = jenksNaturalBreaks(rows.map(i => Number(i[x.length]||0 )||0 ), 5);\\n    // 提取省份和值\\n    const mapData = rows.map((col, index) => ({\\n        name: rows[index][0], // 省份\\n        value: rows[index][x.length] // 值\\n    }));\\n    // 返回 ECharts 配置\\n    // @ts-ignore\\n    option = {\\n        ...option,\\n        visualMap: {\\n            type: \'piecewise\', // 设置为分段模式\\n            left: \'right\', // 视觉图例位置\\n            top: \'center\',\\n            width: \'10%\', // 可选：控制宽度\\n            height: \'80%\', // 可选：控制高度\\n            min: 0, // 数据的最小值\\n            max: 1000, // 数据的最大值\\n            splitNumber: 5, // 分成几段（如果设置了 pieces，会忽略 splitNumber）\\n            pieces: intervals.map((i, idx) => ({\\n                min: i.min,\\n                max: i.max,\\n                color: [\'#d94e5d\', \'#eac736\', \'#50a3ba\', \'#91c7ae\', \'#516b91\'][intervals.length - idx - 1],\\n            })),\\n            text: [\'高\', \'低\'], // 文本显示（顶部为高，底部为低）\\n            textStyle: {\\n                color: dark ? \'#fff\' : \'#000\' // 文本颜色，dark 模式为白色\\n            },\\n            show: true, // 是否显示 visualMap 组件\\n        },\\n        series: [\\n            {\\n                type: \'map\',  // 保持为 map 类型\\n                map: \'china\',\\n                roam: true, // 启用地图的缩放和平移\\n                label: {\\n                    show: true, // 显示省份名称\\n                    color: \'#444\',  // 标签文字颜色\\n                },\\n                itemStyle: {\\n                    areaColor: dark ? \'#aaa\' : \'#f5f5f5\', // 无数据区域颜色\\n                    borderColor: dark ? \'#555\' : \'#999\', // 区域边框颜色\\n                },\\n                // top: \'1%\',\\n                // zoom: 1.5,\\n                // center: [104.114129, 37.550339],\\n                layoutCenter: [\'50%\', \'50%\'], // 地图中心相对容器居中\\n                layoutSize: \'100%\',\\n                tooltip: {\\n                    trigger: \'item\',  // 设置为 item 类型，显示每个省份的 tooltip\\n                    formatter: \'{b}: {c}\',  // 显示省份名称和对应的值\\n                },\\n                geoIndex: 0,\\n                data: mapData\\n            }\\n        ]\\n    }\\n\\n    console.log(\'map\', option)\\n    return { option }\\n}\", \"allowEmptyData\": true}', 'MAP', '1', '0', '1', '1752812306359', '0', '', '7', 'echarts', 'icon-map'),
	('8', '漏斗图', '一个比较简单的漏斗图', '{\"icon\": \"icon-funnel\", \"limit\": [{\"x\": 1, \"y\": 1}, {\"x\": 0, \"y\": [2, 100]}], \"script\": \"function main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    const list = transpose(rows)\\n    let option: any = {\\n        legend: {\\n            orient: \'horizontal\',\\n        },\\n        backgroundColor: \'transparent\'\\n    }\\n    // 统一处理漏斗数据的逻辑\\n    const generateFunnelData = (x: string[], y: string[]) => {\\n        if (x.length === 0) {\\n            // 没有 X 轴时，将列名作为漏斗层级，值来自行\\n            return y.map((column, idx) => ({\\n                name: column,\\n                value: rows[0][idx],\\n            }));\\n        } else if (x.length === 1 && y.length === 1) {\\n            // 有 X 轴时，根据 group by X 汇总生成漏斗层级\\n            const xValues = rows.map(row => row[columns.indexOf(x[0])]);\\n            const yValues = rows.map(row => row[columns.indexOf(y[0])]);\\n            const grouped = xValues.reduce((acc: Record<string, number>, key, idx) => {\\n                acc[key] = (acc[key] || 0) + yValues[idx];\\n                return acc;\\n            }, {});\\n            return Object.entries(grouped).map(([name, value]) => ({ name, value }));\\n        }\\n        return [];\\n    };\\n\\n    const funnelData = generateFunnelData(x, y);\\n\\n    // 构建漏斗图配置\\n    option = {\\n        ...option,\\n        series: [\\n            {\\n                name: \'漏斗图\',\\n                type: \'funnel\',\\n                data: funnelData,\\n                sort: \'none\', // 按值降序排列\\n                label: {\\n                    position: \'right\', // 标签位置在右侧\\n                    formatter: (params: any) => {\\n                        const index = params.dataIndex;\\n                        const currentValue = params.data.value;\\n                        const nextValue = funnelData[index + 1]?.value;\\n                        if (nextValue !== undefined) {\\n                            const conversionRate = ((nextValue / currentValue) * 100).toFixed(2);\\n                            return `${params.name}\\\\n${params.value}\\\\n转化率: ${conversionRate}%`;\\n                        }\\n                        return `${params.name}\\\\n${params.value}`;\\n                    },\\n                },\\n                labelLine: {\\n                    show: true,\\n                    length: 10,\\n                    length2: 20,\\n                },\\n                itemStyle: {\\n                    borderColor: \'#fff\',\\n                    borderWidth: 1,\\n                },\\n            },\\n        ],\\n    };\\n    return { option }\\n}\"}', 'FUNNEL', '1', '0', '1', '1737453191156', '0', '', '8', 'echarts', 'icon-funnel'),
	('9', '堆叠柱形图', '一个比较简单的堆叠柱形图', '{\"icon\": \"icon-stacked_column\", \"limit\": [{\"x\": [1, 2], \"y\": [2, 100]}], \"script\": \"function main(args) {\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args\\n    let config = renderConfig[chartType.toLowerCase()] || {}\\n    const list = transpose(rows)\\n    let option: any = {\\n        legend: {\\n            orient: \'horizontal\',\\n        },\\n        backgroundColor: \'transparent\'\\n    }\\n    return { option }\\n}\"}', 'STACKED_COLUMN', '1', '0', '1', '1737453217860', '0', '', '9', 'echarts', 'icon-stacked_column'),
	('10', '指标卡', '一个比较简单的指标卡', '{\"icon\": \"icon-indicator\", \"limit\": [{\"x\": [0, 2], \"y\": [1, 100]}], \"script\": \"const extractNumbers = (input) => {\\n    const regex = /-?\\\\d+(\\\\.\\\\d+)?/g;\\n    const matches = String(input).match(regex);\\n    return matches ? Number(matches[0]) : null;\\n};\\n\\nfunction calculateTextWidth(text, fontSize) {\\n  if (!text) {\\n    return\\n  }\\n  const numberWidth = fontSize * 0.6; // 数字宽度\\n  const punctuationWidth = fontSize * 0.3; // 逗号、小数点宽度\\n  const chineseWidth = fontSize * 1; // 中文字符宽度\\n\\n  let totalWidth = 0;\\n\\n  for (const char of text.toString()) {\\n    if (/[0-9]/.test(char)) {\\n      totalWidth += numberWidth; // 数字\\n    } else if (/[,\\\\.]/.test(char)) {\\n      totalWidth += punctuationWidth; // 逗号、小数点\\n    } else if (/[\\\\u4e00-\\\\u9fa5]/.test(char)) {\\n      totalWidth += chineseWidth; // 中文字符\\n    }\\n  }\\n\\n  return totalWidth;\\n}\\nconst { useEffect, useRef } = React\\n\\nconst paddingPercent = .2\\nconst minPercent = .6\\nconst INDICATOR = ({ args }) => {\\n    const { data, width } = args;\\n    const getZoom = (value) => {\\n        let valueWidth = calculateTextWidth(value, 24)\\n        if (!width || !valueWidth) {\\n            return 1\\n        }\\n        return Math.min(1.2, (width * (1 - paddingPercent) * minPercent) / valueWidth) / 1.1\\n    }\\n    const fields = data.columns;\\n    // const { ref, getZoom } = useZoom(24);\\n\\n    const getValue = (index) => {\\n        const label = fields?.[index];\\n        if (!label) return;\\n        let value = data.rows[0]?.[index];\\n        if (!value) return { label, value: \\\"-\\\" };\\n\\n        const percent = value?.toString().includes(\\\"%\\\");\\n        const number = extractNumbers(value);\\n        let classNames = percent ? \\\"indicator_percent\\\" : \\\"\\\";\\n        if (number) {\\n            classNames += number > 0 ? \\\" positive\\\" : \\\" negative\\\";\\n        }\\n\\n        return { label, value, classNames };\\n    };\\n\\n    const value1 = getValue(0);\\n    const value2 = getValue(1);\\n    const zoom = getZoom(value1?.value);\\n\\n    return (\\n        <div\\n            // ref={ref}\\n            className={`m-auto select-none overflow-hidden relative justify-center items-center w-full h-full flex indicator-container indicator_card_wrapper indicator_card_default`}>\\n            <div className=\\\"icon indicator_image\\\" style={{zoom}}>\\n                {/* <MyIcon name=\'dataTable\' /> */}\\n            </div>\\n            < div className=\\\"values indicator_content\\\" style={{zoom}}>\\n                {value1 && (\\n                    <div className=\\\"value1\\\" >\\n                        <div className=\\\"relative text-sm text-gray-400 dark:text-gray-600 label indicator_name\\\" >\\n                            {value1.label}\\n                        </div>\\n                        < span\\n                            className={`text-3xl text-gray-700 dark:text-gray-300 number indicator_value ${value1?.classNames}`}\\n                        >\\n                            {value1.value}\\n                        </span>\\n                    </div>\\n                )}\\n                {\\n                    value2 && (\\n                        <div className=\\\"flex text-xl justify-start items-center value2\\\" >\\n                            <div className={\'flex items-center text-md label\'}>\\n                                <div className={`text-gray-600 dark:text-gray-400 indicator_value number ${value2.classNames}`}>\\n                                    {value2.value}\\n                                </div>\\n                            </div>\\n                            < div className=\\\"ml-2 text-sm text-gray-400 dark:text-gray-600 label\\\" >\\n                                {value2.label}\\n                            </div>\\n                        </div>\\n                    )\\n                }\\n            </div>\\n        </div>\\n    );\\n};\"}', 'INDICATOR', '1', '0', '1', '1753875531793', '0', '', '1', 'react', 'icon-indicator'),
	('11', '金额指标卡', '一个比较简单的金额指标卡', '{\"icon\": \"icon-amount_indicator\", \"limit\": [{\"x\": [0, 2], \"y\": [1, 100]}], \"script\": \"// import classNames from \\\"classnames\\\";\\n\\nconst AMOUNT_INDICATOR = ({ args }) => {\\n    const {yColumns, data} = args\\n    // const { value, digit = 2 } = props; // digit 默认值为 2\\n    const value = data.rows?.[0]?.[0]\\n    const digit = yColumns[0]?.valueProps?.digit || 2\\n    // 转换金额\\n    const amount = Number(value || 0);\\n    const [integerPart, decimalPart = \'\'] = String(amount).split(\'.\');\\n\\n    // 生成整数部分（补齐 10 位）\\n    const integerArray = [...integerPart.padStart(10, \'0\')];\\n\\n    // 小数部分：根据 digit 补齐或截断\\n    const decimalArray = [...decimalPart.padEnd(digit, \'0\').slice(0, digit)];\\n\\n    // 单位配置，仅应用于整数部分\\n    const units = [\'十亿\', \'亿\', \'千万\', \'百万\', \'十万\', \'万\'];\\n\\n    // 整数部分元素\\n    const integerElements = integerArray.map((digit, index) => (\\n        <div key={`int-${index}`} className=\\\"relative flex flex-row items-end\\\"\\n            style={{ width: \'calc(9.5% - 4px)\', fontSize: \'3%\' }}>\\n            {/* 单位标识，仅整数部分适用 */}\\n            {index <= units.length && (\\n                <div className=\\\"absolute text-gray-500\\\"\\n                    style={{\\n                        fontSize: \'13px\',\\n                        top: \'-15px\',\\n                        left: \'4px\'\\n                    }}>\\n                    {units[index]}\\n                </div>\\n            )}\\n            {/* 数字展示 */}\\n            <div className={\\n                `w-full flex items-center justify-center m-1 text-2xl font-bold ${index < 10 - integerPart.length\\n                    ? \'bg-gray-100 dark:bg-antdDarkColorFillTertiary text-gray-400 dark:text-gray-600\'\\n                    : \'bg-gray-300 dark:bg-antdDarkColorFill dark:text-gray-100\'}`\\n            }>\\n                {digit}\\n            </div>\\n            {/* 千分位逗号逻辑 */}\\n            {(index > 0 && (integerArray.length - index) % 3 === 0) && (\\n                <div className=\\\"comma text-4xl\\\">\\n                    ,\\n                </div>\\n            )}\\n        </div>\\n    ));\\n\\n    // 小数部分元素\\n    const decimalElements = decimalArray.map((digit, index) => (\\n        <div key={`dec-${index}`} className=\\\"flex flex-row items-end\\\"\\n            style={{ width: \'calc(9.5% - 4px)\', fontSize: \'3%\' }}>\\n            <div className=\\\"w-full flex items-center justify-center m-1 text-2xl font-bold bg-gray-300 dark:bg-antdDarkColorFill dark:text-gray-100\\\">\\n                {digit}\\n            </div>\\n        </div>\\n    ));\\n\\n    return (\\n        <div className=\\\"select-none cursor-default w-full h-full flex justify-center items-center m-auto dark:text-gray-100\\\"\\n            style={{ width: \'calc(100% - 40px)\' }}>\\n            <div className=\\\"flex flex-row w-full\\\" style={{ height: \'40px\' }}>\\n                {integerElements}\\n                {/* 小数点 */}\\n                {decimalArray.length > 0 && (\\n                    <div className=\\\"comma text-4xl\\\">.</div>\\n                )}\\n                {/* 小数部分 */}\\n                {decimalElements}\\n            </div>\\n        </div>\\n    );\\n};\\n\"}', 'AMOUNT_INDICATOR', '1', '0', '1', '1739240779767', '0', '', '1', 'react', 'icon-amount_indicator'),
	('12', '排行榜', '一个比较简单的排行榜', '{\"icon\": \"icon-jiangbei\", \"limit\": [{\"x\": [0, 2], \"y\": [1, 100]}], \"script\": \"const RANK_LIST = ({ args }) => {\\n    const { data } = args;\\n    const { rows, columns } = data;\\n    console.log(rows)\\n\\n\\n    // 获取前三个数据\\n    const topThree = rows.slice(0, 3);\\n    const restRows = rows.slice(3);\\n    console.log(topThree, restRows)\\n\\n    return (\\n        <div className=\\\"relative h-full overflow-auto p-6 dark:bg-gray-900 dark:text-white\\\">\\n            {/* 排行前三 */}\\n            <div className=\\\"flex justify-between items-center mb-6\\\">\\n                {/* 第二名左侧显示 */}\\n                {topThree.length > 1 && <div className=\\\"flex flex-col items-center bg-white p-4 rounded-lg shadow-md w-1/3 dark:bg-gray-800 dark:text-white\\\">\\n                    <div className=\\\"text-4xl font-bold text-gray-800 dark:text-gray-100\\\">2</div>\\n                    {columns.map((col, colIndex) => (\\n                        <div key={colIndex} className=\\\"mt-2 text-gray-600 dark:text-gray-300\\\">\\n                            <span className=\\\"font-semibold\\\">{col}:</span> {topThree[1][colIndex]}\\n                        </div>\\n                    ))}\\n                </div>}\\n                {/* 第一名居中显示 */}\\n                {topThree.length > 0 && <div className=\\\"flex flex-col items-center bg-white p-4 rounded-lg shadow-md w-1/3 dark:bg-gray-800 dark:text-white transform translate-y-[-10px]\\\">\\n                    <div className=\\\"text-4xl font-bold text-gray-800 dark:text-gray-100\\\">1</div>\\n                    {columns.map((col, colIndex) => (\\n                        <div key={colIndex} className=\\\"mt-2 text-gray-600 dark:text-gray-300\\\">\\n                            <span className=\\\"font-semibold\\\">{col}:</span> {topThree[0][colIndex]}\\n                        </div>\\n                    ))}\\n                </div>}\\n                {/* 第三名右侧显示 */}\\n                {topThree.length > 2 && <div className=\\\"flex flex-col items-center bg-white p-4 rounded-lg shadow-md w-1/3 dark:bg-gray-800 dark:text-white\\\">\\n                    <div className=\\\"text-4xl font-bold text-gray-800 dark:text-gray-100\\\">3</div>\\n                    {columns.map((col, colIndex) => (\\n                        <div key={colIndex} className=\\\"mt-2 text-gray-600 dark:text-gray-300\\\">\\n                            <span className=\\\"font-semibold\\\">{col}:</span> {topThree[2][colIndex]}\\n                        </div>\\n                    ))}\\n                </div>}\\n            </div>\\n\\n            {/* 剩余数据渲染为表格 */}\\n            {restRows.length > 0 && <table className=\\\"min-w-full table-auto border-collapse border border-gray-300 dark:border-gray-600\\\">\\n                <thead className=\\\"bg-gray-100 dark:bg-gray-700\\\">\\n                    <tr>\\n                        {columns.map((col, index) => (\\n                            <th key={index} className=\\\"px-4 py-2 text-left text-sm font-semibold text-gray-700 dark:text-gray-300 border-b border-gray-200 dark:border-gray-600\\\">\\n                                {col}\\n                            </th>\\n                        ))}\\n                    </tr>\\n                </thead>\\n                <tbody>\\n                    {restRows.map((row, rowIndex) => (\\n                        <tr key={rowIndex} className=\\\"border-b hover:bg-gray-50 dark:hover:bg-gray-600\\\">\\n                            {row.map((item, colIndex) => (\\n                                <td key={colIndex} className=\\\"px-4 py-2 text-sm text-gray-800 dark:text-gray-200\\\">\\n                                    {item}\\n                                </td>\\n                            ))}\\n                        </tr>\\n                    ))}\\n                </tbody>\\n            </table>}\\n        </div>\\n    );\\n};\"}', 'RANK_LIST', '1', '0', '1', '1739241988350', '0', '', '1', 'react', 'icon-jiangbei'),
	('14', '表格测试', '一个比较简单的表格测试', '{\"icon\": \"icon-table\", \"limit\": [{\"x\": [0, 2], \"y\": [1, 100]}], \"script\": \"// import { execTs } from \'@/utils/common/common\';\\n\\n// export interface HighlightProps {\\n//   className?: string\\n//   logical: string\\n//   indexes: number[]\\n// }\\n\\n// interface DataTableProps {\\n//   data: DataSet;\\n//   size: \'mini\' | \'small\';\\n//   pagination?: { pageSize: number; hidden?: boolean, total?: number };\\n//   actions?: (rowData: any[], index: number) => JSX.Element[];\\n//   onColClick?: (rowIndex: number, colIndex: number, value: any) => void\\n//   showIndex?: boolean; // 是否显示索引列\\n//   indexColumnName?: string; // 索引列的自定义名称\\n//   highlights?: HighlightProps[]\\n//   sortedIndexes?: number[]\\n//   hideColumnIndexes?: number[]\\n//   onSortChange?: (index: number, orderBy: SortOrderBy | undefined) => void\\n// }\\n\\nconst TABLE_TEST = ({ args }) => {\\n  const { data: { columns, rows }, renderConfig: { pagination, size,\\n    actions, showIndex, indexColumnName, highlights, onColClick,\\n    sortedIndexes, onSortChange, hideColumnIndexes } } = args\\n  const { useEffect, useRef, useState } = React\\n  const [currentPage, setCurrentPage] = useState(1);\\n  const [hoveredRowIndex, setHoveredRowIndex] = useState(null);\\n  const [hoveredColIndex, setHoveredColIndex] = useState(null);\\n  const pageSize = pagination?.pageSize || 10\\n  const total = pagination?.total || rows.length\\n  const [sorts, setSorts] = useState({})\\n\\n  const handlePrevPage = () => {\\n    setCurrentPage(prevPage => Math.max(prevPage - 1, 1));\\n  };\\n\\n  const handleNextPage = () => {\\n    setCurrentPage(prevPage => Math.min(prevPage + 1,\\n      Math.ceil(total / pageSize)));\\n  };\\n\\n  const handlePageChange = (pager) => {\\n    setCurrentPage(page);\\n  };\\n\\n  const handleCellHover = (rowIndex, colIndex) => {\\n    setHoveredRowIndex(rowIndex);\\n    setHoveredColIndex(colIndex);\\n  };\\n  const hiddenPagination = !pagination || pagination.hidden\\n\\n  const observerRef = useRef(null);\\n\\n  useEffect(() => {\\n    if (!pagination?.hidden) {\\n      setCurrentPage(1)\\n      return\\n    } // 仅在分页隐藏时启用懒加载\\n\\n    const observer = new IntersectionObserver(entries => {\\n      if (entries[0].isIntersecting) {\\n        setCurrentPage(prevPage => prevPage + 1);\\n      }\\n    });\\n\\n    if (observerRef.current) {\\n      observer.observe(observerRef.current);\\n    }\\n\\n    return () => {\\n      if (observerRef.current) {\\n        observer.unobserve(observerRef.current);\\n      }\\n    };\\n  }, [pagination?.hidden]);\\n\\n  const renderPagination = () => {\\n    if (hiddenPagination) {\\n      return\\n    }\\n    const totalPages = Math.ceil(total / pageSize);\\n    const pagesToShow = size === \'mini\' ? 3 : 5; // 要显示的页码数量\\n    const pagesAroundEllipsis = 1; // 省略号两侧要显示的页码数量\\n\\n    // 计算要显示的页码范围\\n    let startPage = Math.max(1, currentPage - Math.floor(pagesToShow / 2));\\n    let endPage = Math.min(totalPages, startPage + pagesToShow - 1);\\n\\n    // 如果当前显示的页码数量小于要显示的数量，则重新计算\\n    if (endPage - startPage + 1 < pagesToShow) {\\n      startPage = Math.max(1, endPage - pagesToShow + 1);\\n    }\\n\\n    const pages = Array.from({ length: endPage - startPage + 1 }, (_, i) => startPage + i);\\n\\n    return (\\n      <div className= { classNames(\'flex justify-end w-full flex-wrap items-end\', size === \'mini\' ? \'mt-1\' : \' mt-2\')\\n  }>\\n    {/* <span className={classNames(\'mr-3 text-base\', size === \'mini\' ? \'mr-1 text-sm w-full text-right mb-2\' : \'\')}>总页数: {totalPages}</span> */ }\\n    < button\\n  onClick = { handlePrevPage }\\n  disabled = { currentPage === 1\\n}\\nclassName = {\\n  classNames(\'py-1 bg-gray-300 dark:bg-antdDarkColorFill rounded-sm disabled:opacity-50 text-sm mr-1 select-none\',\\n    size === \'mini\' ? \'text-xs mr-1 px-2\' : \'px-3\')}\\n        >\\n  { size === \'mini\' ? \'<\' : \'上一页\'}\\n</button>\\n{\\n  startPage > 1 && (\\n    <>\\n    <button\\n              onClick={ () => handlePageChange(1) }\\n  className = {\\n    classNames(`py-1  dark:bg-antdDarkBorder rounded-sm text-sm mx-1`,\\n                1 === currentPage ? \' text-white dark:text-black\' : \'bg-gray-200\',\\n    size === \'mini\' ? \'text-xs px-2\' : \'px-3 mx-1 text-sm\')\\n}\\n            >\\n  1\\n  </button>\\n{ startPage > 2 && <span>...</span> }\\n</>\\n        )}\\n{\\n  pages.map(page => (\\n    <button\\n            key= { page }\\n            onClick = {() => handlePageChange(page)}\\nclassName = {\\n  classNames(`select-none py-1 dark:bg-antdDarkBorder  rounded-sm`,\\n    page === currentPage ? \'text-white bg-blue-600 dark:bg-blue-500 font-bold \' : \'bg-gray-200\',\\n  size === \'mini\' ? \'text-xs px-2 mx-1\' : \'px-3 text-sm mx-1\')}\\n          >\\n  { page }\\n  </button>\\n        ))}\\n{\\n  endPage < totalPages && (\\n    <>\\n    { totalPages - endPage > 1 && <span>...</span>\\n}\\n<button\\n              onClick={ () => handlePageChange(totalPages) }\\nclassName = {\\n  classNames(`py-1  dark:bg-antdDarkBorder rounded-sm select-none`,\\n    totalPages === currentPage ? \' text-white\' : \'bg-gray-200\',\\n  size === \'mini\' ? \'text-xs px-2 mx-1\' : \'px-3 mx-1 text-sm\')}\\n            >\\n  { totalPages }\\n  </button>\\n  </>\\n        )}\\n<button\\n          onClick={ handleNextPage }\\ndisabled = { currentPage === totalPages}\\nclassName = {\\n  classNames(\\\"py-1 bg-gray-300 dark:bg-antdDarkColorFill rounded-sm disabled:opacity-50 select-none\\\",\\n    size === \'mini\' ? \'text-xs ml-1 px-2\' : \'px-3 text-sm ml-1\')}\\n        >\\n  { size === \'mini\' ? \'>\' : \'下一页\'}\\n</button>\\n  </div>\\n    );\\n  };\\nconst renderTdContent = (value) => {\\n  if (typeof value === \'object\') {\\n    return JSON.stringify(value)\\n  } else if (typeof value === \'string\') {\\n    if (value.startsWith(\'https\') || value.startsWith(\'http\')) {\\n      if (isImage(value)) {\\n        return <img height={ 100 } width = { 100} src = { value } />\\n        }\\n      return <a target=\'_blank\' className = \' text-blue-600\'\\n      href = { value } > { value.substring(value.lastIndexOf(\'/\') + 1, value.length) } </a>\\n    }\\n  }\\n  return value\\n}\\n\\nconst isImage = (url) => {\\n  const list = [\'png\', \'jpg\', \'jpeg\', \'avif\', \'gif\']\\n  for (let i = 0; i < list.length; i++) {\\n    if (url.endsWith(list[i]) || url.endsWith(list[i].toUpperCase())) {\\n      return true\\n    }\\n  }\\n  return false\\n}\\n\\nconst renderTableHeader = () => {\\n  const classNameList = [\\\"py-1 border border-gray-200 dark:border-antdDarkBorder text-left bg-transparent whitespace-nowrap select-none\\\",\\n    size === \'mini\' ? \'text-xs px-2 py-2\' : \' text-sm px-3 py-2.5\',]\\n  const className = classNames(classNameList);\\n  // 用shadow来处理sticky border问题\\n  return (<tr className= \\\"border-0 shadow-sticky dark:shadow-sticky-dark sticky top-0 z-100 bg-antdColorBgLayout dark:bg-antdDarkContainer\\\" >\\n    {/* 显示索引列 */ }\\n  { showIndex && <th className={ className }> { indexColumnName || \'序号\' } </th>\\n}\\n{\\n  columns.length > 0 &&\\n    columns.filter((_, idx) => !hideColumnIndexes || !hideColumnIndexes.includes(idx))\\n      .map((key, index) => {\\n        const sorted = sortedIndexes?.includes(index)\\n        return <th key={ index } className = {\\n          classNames(classNameList,\\n            sorted && \'hover:bg-gray-200/50 dark:hover:bg-black/30 cursor-pointer\'\\n            )\\n}> <div className={ classNames(\'flex items-center \', size === \'mini\' ? \'gap-1\' : \'gap-3\') } onClick = {() => {\\n  if (!sorted) return\\n  const orderBy = !sorts[index] ? \'ASC\' : (sorts[index] === \'ASC\' ? \'DESC\' : undefined);\\n  setSorts({ [index]: orderBy })\\n  onSortChange?.(index, orderBy)\\n}}> { key } {\\n  sorted && <div><MyIcon size={ size === \'mini\' ? 12 : 16 }\\n  className = {\\n    classNames(\'\',\\n                !sorts[index]? \'fill-gray-300 dark:fill-antdDarkColorFill\' : \' fill-black dark:fill-white\')\\n  }\\n  name = { sorts[index] || \'ASC\' } />\\n    </div>\\n}\\n</div>\\n  </th>\\n          })}\\n{ actions && actions?.([], 0).length > 0 && <th className={ className }> 操作 </th> }\\n</tr>\\n    );\\n  };\\n\\n// 修改 renderTableBody 方法来支持懒加载\\nconst renderTableBody = () => {\\n  const startIndex = pagination?.hidden ? 0 : (currentPage - 1) * pageSize;\\n  const endIndex = pagination?.hidden ? currentPage * pageSize : Math.min(startIndex + pageSize, total);\\n\\n  const className = (rowIndex, colIndex, value) => {\\n    let baseClass = [\\n      \\\"py-1 border border-gray-200 dark:border-antdDarkBorder whitespace-nowrap select-none\\\",\\n      size === \'mini\' ? \'text-xs px-1 py-0.5\' : \'px-3 py-2 text-sm\',\\n      hoveredRowIndex === rowIndex && hoveredColIndex === colIndex\\n        ? \'bg-gray-400 bg-opacity-30 dark:bg-antdDarkColorFillSecondary\'\\n        : hoveredRowIndex === rowIndex || hoveredColIndex === colIndex\\n          ? \'bg-antdColorBgLayout dark:bg-antdDarkBorder bg-opacity-30 dark:bg-antdDarkColorFillQuaternary\'\\n          : \'bg-transparent\'\\n    ]\\n\\n    // 高亮逻辑\\n    // highlights?.forEach(i => {\\n    //   if (i.indexes.includes(colIndex)) {\\n    //     const values = rows.map(row => row[colIndex])\\n    //     const result = execTs(i.logical, { values, value })\\n    //     if (result) baseClass.push(i.className)\\n    //   }\\n    // })\\n    return classNames(baseClass);\\n  };\\n\\n  return rows.slice(startIndex, endIndex).map((item, rowIndex) => {\\n    const doms = actions?.(item, rowIndex);\\n    return (\\n      <tr key= { rowIndex } >\\n      {/* 显示索引列 */ }\\n    {\\n      showIndex && (\\n        <td className={ className(rowIndex, -1, startIndex + rowIndex + 1) }> { startIndex + rowIndex + 1\\n    } </td>\\n          )\\n}\\n{\\n  item.filter((_, idx) => !hideColumnIndexes || !hideColumnIndexes.includes(idx)).map((value, colIndex) => {\\n    const colName = columns[colIndex]; // 获取列名\\n    return (\\n      <td\\n                key= { colIndex }\\n    className = { className(rowIndex, colIndex, value) }\\n    onMouseEnter = {() => handleCellHover(rowIndex, colIndex)\\n  }\\n                onMouseLeave = {() => handleCellHover(null, null)}\\nonClick = {() => onColClick?.(rowIndex, colIndex, value)}\\n              >\\n  { renderTdContent(value) }\\n  </td>\\n            );\\n          })}\\n{\\n  doms && doms.length > 0 && (\\n    <td className={ className(rowIndex, item.length, \'\') }>\\n    {\\n      doms.map((dom, index) =>\\n        React.cloneElement(dom, {\\n          key: index,\\n          className: classNames(\\n            dom.props.className, // 保留原始className\\n            size === \'mini\' ? \'text-xs\' : \'text-sm\' // 添加动态class\\n          ),\\n        })\\n      )\\n    }\\n      </td>\\n          )\\n}\\n</tr>\\n      );\\n    });\\n  };\\nif (total == 0) {\\n  return <div className=\' flex justify-center\' > 没有数据 </div>\\n}\\n\\nreturn (\\n  <div className= \\\"relative w-full h-full overflow-hidden text-black dark:text-white flex flex-col justify-between\\\" >\\n  <div className=\\\"w-full\\\" style = {{ flex: 1, overflow: \'hidden\' }}>\\n    <div className=\'h-full w-full relative overflow-y-auto\' >\\n      <table className=\\\"min-w-full bg-transparent border-gray-200 dark:border-antdDarkBorder border-collapse bg-white dark:bg-black\\\" >\\n        <thead>\\n        { renderTableHeader() }\\n        </thead>\\n        <tbody>\\n{ renderTableBody() }\\n</tbody>\\n  </table>\\n  </div>\\n{ pagination?.hidden && <div ref={ observerRef } className = \\\"observer-element\\\" > </div> }\\n</div>\\n{\\n  !pagination?.hidden && (pageSize < total) &&\\n    <div className={ classNames(size === \'mini\' ? \'text-xs\' : \'text-sm\') } style = {{ flex: \'0 0 40px\' }\\n}>\\n  { renderPagination() }\\n  </div>}\\n</div>\\n  );\\n};\\n\"}', 'TABLE_TEST', '1', '0', '1', '1739240798213', '0', '', '1', 'react', 'icon-table'),
	('16', '图片', '一个比较简单的图片', '{\"icon\": \"icon-image\", \"limit\": [{\"x\": [0, 100], \"y\": [0, 100]}], \"script\": \"const { useState } = React\\nconst IMAGE = ({ args }) => {\\n    // 数据、元数据、配置\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args;\\n    // 解构自定义选项\\n    const { imageUrl } = renderConfig[chartType.toLowerCase()] || {};\\n\\n    // 预览状态\\n    const [isPreviewVisible, setPreviewVisible] = useState(false);\\n\\n    // 显示预览\\n    const showPreview = () => {\\n        setPreviewVisible(true);\\n    };\\n\\n    // 关闭预览\\n    const hidePreview = () => {\\n        setPreviewVisible(false);\\n    };\\n\\n    return (\\n        <div style={{ position: \'relative\', width: \'100%\', height: \'100%\' }}>\\n            {/* 事件绑定到 div 上 */}\\n            <div \\n                style={{ maxWidth: \'100%\', maxHeight: \'100%\', cursor: \'pointer\' }} \\n                onClick={showPreview} // 点击 div 显示预览\\n            >\\n                <img \\n                    src={imageUrl} \\n                    alt=\\\"image\\\" \\n                    style={{ maxWidth: \'100%\', maxHeight: \'100%\', objectFit: \'cover\' }}\\n                />\\n            </div>\\n\\n            {/* 使用 React Portal 将预览弹框挂载到 root 元素下 */}\\n            {isPreviewVisible && ReactDOM.createPortal(\\n                <div \\n                    style={{\\n                        position: \'fixed\', top: 0, left: 0, right: 0, bottom: 0,\\n                        backgroundColor: \'rgba(0, 0, 0, 0.75)\', display: \'flex\',\\n                        justifyContent: \'center\', alignItems: \'center\', zIndex: 9999\\n                    }}\\n                    onClick={hidePreview} // 点击背景关闭预览\\n                >\\n                    <div \\n                        style={{\\n                            position: \'relative\', maxWidth: \'90%\', maxHeight: \'90%\',\\n                            backgroundColor: dark? \'rgb(20, 20, 20)\':\'white\', padding: \'20px\', overflow: \'auto\',\\n                            borderRadius: \'8px\',\\n                            boxShadow: \'0px 4px 12px rgba(0, 0, 0, 0.3)\' // 使弹框有阴影效果\\n                        }}\\n                        onClick={(e) => e.stopPropagation()} // 阻止点击图片时关闭预览\\n                    >\\n                        <img \\n                            src={imageUrl} \\n                            alt=\\\"preview\\\" \\n                            style={{\\n                                width: \'100%\', height: \'auto\', objectFit: \'contain\'\\n                            }} \\n                        />\\n                        <button \\n                            onClick={hidePreview} \\n                            style={{\\n                                position: \'absolute\', top: \'10px\', right: \'10px\', \\n                                backgroundColor: \'gray\', color: \'white\', border: \'none\',\\n                                padding: \'2px 8px\', borderRadius: \'50%\', cursor: \'pointer\',\\n                                fontSize: \'16px\', fontWeight: \'bold\',\\n                                lineHeight: \'21px\'\\n                            }}\\n                        >\\n                            ×\\n                        </button>\\n                    </div>\\n                </div>,\\n                document.body // 将预览弹框挂载到 body 元素下（也可以挂载到 root 元素）\\n            )}\\n        </div>\\n    );\\n};\", \"confItemsMap\": {\"图片配置\": [{\"label\": \"图片链接\", \"fieldName\": \"imageUrl\", \"componentType\": \"textarea\"}]}, \"allowEmptyData\": true}', 'IMAGE', '1', '1739254738249', '1', '1739337505570', '0', '1', NULL, 'react', 'icon-image'),
	('17', '文本', '一个比较简单的文本', '{\"limit\": [{\"x\": [0, 100], \"y\": [0, 100]}], \"script\": \"const { useEffect, useRef } = React;\\n\\nconst TEXT = ({ args }) => {\\n    // 数据、元数据、配置\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args;\\n    // 解构自定义选项\\n    const { title1, fontSize } = renderConfig[chartType.toLowerCase()] || {};\\n    \\n    return (\\n        <div \\n            style={{\\n                fontSize,\\n                display: \'flex\',\\n                justifyContent: \'center\',\\n                alignItems: \'center\',\\n                height: \'100%\' // 可根据需要调整或设置固定高度\\n            }}\\n        >\\n            {title1}\\n        </div>\\n    );\\n};\", \"confItemsMap\": {\"文本配置\": [{\"label\": \"标题1\", \"fieldName\": \"title1\", \"componentType\": \"textarea\"}, {\"label\": \"字体大小\", \"fieldName\": \"fontSize\", \"optionArray\": [8, 10, 12, 14, 16, 18, 20, 24, 28, 32, 40], \"componentType\": \"select\"}]}, \"allowEmptyData\": true}', 'TEXT', '1', '1739328846180', '1', '1739330324523', '0', '1', NULL, 'react', 'icon-text'),
	('18', '网页', '一个比较简单的网页', '{\"limit\": [{\"x\": [0, 100], \"y\": [0, 100]}], \"script\": \"const WEB = ({ args }) => {\\n    // 数据、元数据、配置\\n    const { data: { columns, rows, x, y }, chartType, mobile, transpose, key, dark, renderConfig } = args;\\n    // 解构自定义选项\\n    const { url } = renderConfig[chartType.toLowerCase()] || {};\\n\\n    return (\\n        <div className=\\\"h-full w-full\\\">  \\n            {/* 组件「WEB」逻辑 */}\\n            <div className=\\\"iframe-container h-full relative w-full\\\">\\n                <iframe \\n                    src={`${url}${dark?\'&theme=dark\':\'\'}`}  // 嵌套的网页 URL\\n                    width=\\\"100%\\\" \\n                    height=\\\"100%\\\"  // 高度设置为100%以自适应容器\\n                    title=\\\"嵌套网页\\\"\\n                    frameBorder=\\\"0\\\"\\n                    style={{ display: \'block\' }}  // 防止 iframe 旁边出现空隙\\n                ></iframe>\\n            </div>\\n        </div>\\n    );\\n};\", \"confItemsMap\": {\"文本配置\": [{\"label\": \"链接\", \"fieldName\": \"url\", \"componentType\": \"textarea\"}]}, \"allowEmptyData\": true}', 'WEB', '1', '1739330662266', '1', '1739338823204', '0', '1', NULL, 'react', 'icon-web'),
	('19', '轮播图', '一个比较简单的轮播图', '{\"limit\": [{\"x\": [0, 100], \"y\": [0, 100]}], \"script\": \"const {useEffect, useRef, useState} = React\\nconst IMAGE_MARQUEE = ({ args }) => {\\n    // 解析数据、元数据、配置\\n    const { data: { rows }, chartType, renderConfig } = args;\\n\\n    // 提取图片列表\\n    const imageList = rows.map(i => i[0]);\\n\\n    // 解析配置\\n    const { interval=3, direct = \'左\' } = renderConfig[chartType.toLowerCase()] || {};\\n\\n    // 轮播逻辑\\n    const [currentIndex, setCurrentIndex] = useState(0);\\n    const intervalRef = useRef(null);\\n\\n    useEffect(() => {\\n        intervalRef.current = setInterval(() => {\\n            setCurrentIndex(prevIndex => \\n                direct === \'左\' \\n                ? (prevIndex + 1) % imageList.length  // 向左轮播\\n                : (prevIndex - 1 + imageList.length) % imageList.length // 向右轮播\\n            );\\n        }, interval * 1000);\\n\\n        return () => clearInterval(intervalRef.current);\\n    }, [interval, direct, imageList.length]);\\n\\n    return (\\n        <div style={{ width: \'100%\', height: \'100%\', overflow: \'hidden\', position: \'relative\' }}>\\n            <div style={{\\n                display: \'flex\',\\n                width: \'100%\',\\n                height: \'100%\',\\n                transition: \'transform 0.5s ease-in-out\',\\n                transform: `translateX(${direct === \'左\' ? -currentIndex * 100 : currentIndex * 100}%)`\\n            }}>\\n                {imageList.map((src, index) => (\\n                    <div key={index} style={{\\n                        width: \'100%\',\\n                        height: \'100%\',\\n                        display: \'flex\',\\n                        justifyContent: \'center\',\\n                        alignItems: \'center\',\\n                        flexShrink: 0\\n                    }}>\\n                        <img src={src} alt={`image-${index}`}\\n                            style={{\\n                                maxWidth: \'100%\',  // 图片不会超出 div 宽度\\n                                maxHeight: \'100%\', // 图片不会超出 div 高度\\n                                objectFit: \'contain\' // 保证完整显示，不裁剪\\n                            }} />\\n                    </div>\\n                ))}\\n            </div>\\n        </div>\\n    );\\n};\", \"confItemsMap\": {\"轮播设置\": [{\"label\": \"方向\", \"fieldName\": \"direction\", \"optionArray\": [\"左\", \"右\"], \"componentType\": \"segmented\"}, {\"label\": \"轮播间隔/毫秒\", \"fieldName\": \"interval\", \"optionArray\": [0.5, 1, 3, 5], \"componentType\": \"select\"}]}, \"allowEmptyData\": true}', 'IMAGE_MARQUEE', '1', '1739331687620', '1', '1743668439130', '0', '1', NULL, 'react', 'icon-marquee');
